void lm_priority_input(apollo_overlay_state *s,p66_bias_io *io,uint16_t n){uint8_t i;throttle_bridge_input(s,io,n);s->words[0]=(uint16_t)(((n%31u)+1u)*01000u);s->words[2]=02553;s->words[3]=(uint16_t)((n%8u)*0400u);s->words[4]=(uint16_t)(((n/8u)%32u)*02000u);s->words[6]=(uint16_t)(s->words[4]|(s->words[3]>>8));s->words[5]=05146;s->words[0167]=(uint16_t)(020000u+(n&0777u));s->words[0166]=0110;s->words[0121]=(uint16_t)(n%4u==3u?AGC_NEG_ZERO:n%3u);io->superbank=(uint16_t)((n%8u)*020u);io->interrupt_enabled=(uint16_t)(n%2u);for(i=1;i<8u;++i){uint16_t a=(uint16_t)(0154u+i*12u);s->words[a+8u]=(uint16_t)(02000u+i);s->words[a+9u]=(uint16_t)(02000u*((i+n)%32u)|((i+n)%8u)|(((i+n)%8u)*020u));s->words[a+10u]=(uint16_t)(n%3u?0110u:077667u);s->words[a+11u]=(uint16_t)(01000u*(((uint32_t)n*13u+(uint32_t)i*7u)%31u+1u)+(i*17u));if((n+i)%5u==0u)s->words[a+11u]=AGC_NEG_ZERO;else if((n+i)%5u==1u)s->words[a+11u]=agc_negate(s->words[a+11u]);}if(n<128u){uint16_t packed=(uint16_t)(033000u+(n&0777u));s->words[0]=033000;for(i=1;i<8u;++i)s->words[0167u+i*12u]=AGC_NEG_ZERO;if(n>=16u&&n<64u){i=(uint8_t)(n%7u+1u);s->words[0167u+i*12u]=(uint16_t)(packed+(n<32u?1u:2u));}else if(n>=64u){s->words[0167u+12u]=037777;s->words[0167u+84u]=n<96u?037777:037776;}}}
